    Home,
    Settings,
    Search,
    Menu,
    Close,
    Cloud,
    ChevronLeft,
    ChevronRight,
    ChevronUp,
    ChevronDown,
    ArrowLeft,
    ArrowRight,
    Add,
    Remove,
    Check,
