    Stop,
    SkipBack,
    SkipForward,
    Volume,
    VolumeMute,
    Shuffle,
    Repeat,
    Info,
    Warning,
    Error,
    Success,
    Heart,
    Star,
    User,
    Users,
    Lock,
    Logout,
    Bell,
    Folder,
    File,
    Image,
    Music,
    Grid,
    List,
    Filter,
}

