     /// A system font with an exact size + weight.
     pub const fn system_weight(size: f32, weight: f32) -> Self {
         Self {
             style: None,
             family: None,
             size: Some(size),
             weight: Some(weight),
             design: None,
         }
     }

     /// A fully-custom typography: family + size + weight + design.
     pub const fn custom_full(
         family: &'static str,
         size: f32,
         weight: f32,
         design: FontDesign,
     ) -> Self {
         Self {
             style: None,
             family: Some(family),
             size: Some(size),
             weight: Some(weight),
             design: Some(design),
         }
     }
