         let node = text("x")
             .modifiers(Frame::new(
                 Some(f32::INFINITY),
                 Some(f32::INFINITY),
                 Some(Align::Leading),
             ))
             .build();
         assert_eq!(
             node.properties.get(&property_id::WIDTH),
             Some(&size::FILL.to_bits())
