                                         .trackIndex(trackIndex.signal())
                                         .position(position.signal())
                                         .playing(playing.signal())
                                         .volume(volume.signal())
                                         .seekRequest(seekRequest.signal())
                                         .volumeRequest(volumeRequest.signal()))
