    @Override
    public Config config() {
        return config;
    }

    @Override
    public View body() {
        return VStack
                .modifiers(
                        Padding.with(24),
                        Background.with(MusicPlayerView.SIDEBAR_BG),
                        Frame.with(f -> f.width(MusicPlayerView.SIDEBAR_WIDTH).height(Commands.Size.FILL)))
                .with(v -> v.alignment(HorizontalAlignment.LEADING).spacing(14))
                .children(
                        Text.with("Now Playing").modifiers(
                                FontSize.with(18), FontWeight.BOLD, AccessibilityRole.with(Roles.HEADER)),
                        Image.with(computed(() -> MusicPlayerView.at(config.trackIndex.get()).cover())).modifiers(
                                Frame.with(f -> f.width(220).height(220)),
                                ScaledToFill.with(),
                                Border.with(b -> b.color(Color.BLACK).width(1).radius(8))),
                        Text.with(computed(() -> MusicPlayerView.at(config.trackIndex.get()).title()))
                                .modifiers(FontSize.with(20), FontWeight.BOLD),
                        Text.with(computed(() -> MusicPlayerView.at(config.trackIndex.get()).artist()
                                + " · " + MusicPlayerView.at(config.trackIndex.get()).album()))
                                .modifiers(ForegroundStyle.with(MusicPlayerView.SECONDARY_FG)),
                        Divider.modifiers(Padding.with(p -> p.edges(0, 0, 0, 10))),
                        Text.with("Up Next").modifiers(FontWeight.SEMIBOLD),
                        upNextRow(1),
                        upNextRow(2));
    }

    /** The track {@code offset} places after the current one. */
    private View upNextRow(int offset) {
        return Text.with(computed(() -> {
            Track track = MusicPlayerView.at(config.trackIndex.get() + offset);
            return (offset == 1 ? "Up next · " : "Then · ") + track.title() + " — " + track.artist();
        })).modifiers(FontSize.with(13), ForegroundStyle.with(MusicPlayerView.SECONDARY_FG));
    }
}

