-                Fit.of(Text.with(t -> t.text("compact")))));
+        View root = VStack.children(SizeThatFits.make(Fit.of(Text.make(t -> t.text("wide")), 640f),
+                Fit.of(Text.make(t -> t.text("compact")))));
