                 sawRoute = true;
             }
         }
         assertTrue(sawRoute, "navigating re-emits the ROUTE property");
         assertTrue(countOps(delta, Categories.PARAMETER, Commands.Parameter.SET_TEXT) >= 1,
                 "the destination text is re-emitted");
     }

