                 .filter(o -> o.category() == Categories.TREE && o.command() == Commands.Tree.CREATE_NODE)
                 .filter(o -> (o.b() & 0xffff) == Components.GRID_ROW)
                 .findFirst()
                 .orElseThrow(() -> new AssertionError("the Grid emits a GRID_ROW node for the GridRow child"));
