         assertEquals(ValueTypes.U32,
                 (sink.frame().opcodes().stream()
                         .filter(o -> (o.b() & 0xFFFF) == Properties.NAV_DEPTH)
                         .findFirst().orElseThrow().b() >>> 16) & 0xFF,
                 "NAV_DEPTH is a U32 property");

         router.push("/users");
