             return this;
         }

         public Config minHeight(float value) {
             return bound(3, value);
         }

         public Config minHeight(Signal<Float> value) {
             bounds[3] = value;
             return this;
         }

         public Config idealHeight(float value) {
             return bound(4, value);
         }

         public Config idealHeight(Signal<Float> value) {
