 /** Test-only: tear a fitted slot's observer down (mirrors CMD_DELETE_NODE). */
 export function destroyFitElement(el: HTMLElement): void {
   const state = fitState.get(el);
   if (state?.observer) {
     state.observer.disconnect();
   }
   fitState.delete(el);
