import { chromium } from 'playwright';

function slot(n) {
  let inner = '';
  for (let i = 0; i < n; i++) {
    const disp = i === 0 ? 'display:contents' : 'display:none';
    inner += `<div data-pathland-fit-cand="${i}" data-pathland-fit-cand-id="${i+2}" style="${disp}"><div data-pathland-id="${i+2}" style="display:flex;flex-direction:row;">C${i}</div></div>`;
  }
  return `<div data-pathland-id="1" class="pathland-ftf" data-pathland-fit="0,640,1024" data-pathland-fit-cands="${n}" style="display:flex;flex-direction:inherit;flex:1 1 auto;align-self:stretch;min-width:0;min-height:0;container-type:inline-size;container-name:pf-1;">${inner}</div>`;
}

function bands(id, ts) {
  let rules = '';
  let seen = -Infinity;
  const n = ts.length;
  for (let i = 0; i < n; i++) {
    const t = ts[i];
    if (i === 0) { seen = t; continue; }
    if (t <= seen) continue;
    seen = t;
    let band = `@container pf-${id} (min-width: ${t}px) {`;
    for (let j = 0; j < n; j++) {
      if (j === i) continue;
      band += ` [data-pathland-id="${id}"] > [data-pathland-fit-cand="${j}"] { display: none !important; }`;
    }
    band += ` [data-pathland-id="${id}"] > [data-pathland-fit-cand="${i}"] { display: contents !important; } }`;
    rules += band + '\n';
  }
  return rules;
}

const css = bands(1, [0, 640, 1024]);
const browser = await chromium.launch({ channel: 'chrome' });
for (const w of [500, 700, 1100, 1400]) {
  const page = await browser.newPage({ viewport: { width: w, height: 800 } });
  const html = `<!DOCTYPE html><html><head><style>html,body{margin:0}body{display:flex;height:100vh}</style><style data-pathland-fit>${css}</style></head><body>${slot(3)}</body></html>`;
