  const info = await page.evaluate(() => {
    const disps = [0,1,2].map(i => getComputedStyle(document.querySelector(`[data-pathland-fit-cand="${i}"]`)).display);
    return { disps, text: document.body.innerText.trim() };
  });
  console.log(w, JSON.stringify(info));
  await page.close();
}
await browser.close();
