  *  reuse and double-parent (spec OPCODE.md — insert/delete ordering). */
 function purgeSubtreeRegistry(host: Element, r: DomRenderer): void {
   const nodes = [
     host,
     ...Array.from(host.querySelectorAll<HTMLElement>("[data-pathland-id]")),
