  // matches slot `10`/`11`… (multi-digit ids are common once nested fit slots
  // exist).
  const marker = new RegExp(`@container pf-${slotId}\\b`);
  const kept: string[] = [];
  let skip = false;
  for (const line of blocks) {
    if (!skip && marker.test(line)) {
      skip = true;
    }
    if (skip) {
      if (line.includes("}")) {
        skip = false;
      }
      continue;
    }
    kept.push(line);

