 interface BatchGlimpse {
   category: number;
   command: number;
   a: number;
   indexBits: number;
 }

 function decode(batch: Uint8Array): BatchGlimpse {
   const parsed = parseBatch(batch);
   const op = parsed.opcodes[0]!;
   return { category: op.category, command: op.command, a: op.a, indexBits: op.b };
 }

