@Test
void resyncBeforeFirstFitChangedEmitsTheSelectedSingleChildOnly() {
    FrameOpcodeSink sink = new FrameOpcodeSink();
    Emitter emitter = new Emitter(sink);
    emitter.snapshotEmission(true);
    View root = VStack.children(SizeThatFits.make(Fit.of(Text.make(t -> t.text("wide")), 640f),
            Fit.of(Text.make(t -> t.text("compact")))));
    emitter.mount(root, Environment.DEFAULT);

    // No FIT_CHANGED yet: a resync must NOT replay the ungated multi-candidate
    // snapshot form (the CSS candidate gate cannot ride opcodes) — it collapses
    // to the selected single child (the threshold-0 fallback) first.
    emitter.renderFull();
    ProtocolFrame resync = sink.frame();
    assertTrue(containsText(resync, "compact"), "resync carries the fallback child");
    assertFalse(containsText(resync, "wide"), "resync does not carry the unselected candidate");
}

