--- lib/java/pathland-observability/src/test/java/dev/pathland/observability/MicrometerTelemetryTest.java	
+++ lib/java/pathland-observability/src/test/java/dev/pathland/observability/MicrometerTelemetryTest.java	
@@ -0,0 +1,64 @@
+package dev.pathland.observability;
+
+import dev.pathland.server.PathlandTelemetry;
+import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
+import org.junit.jupiter.api.Test;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+/**
+ * The Micrometer adapter: each runtime event lands on the expected {@code pathland.*}
+ * meter, tagged by mount, and the active-sessions gauge is pull-based.
+ */
+class MicrometerTelemetryTest {
+
+    @Test
+    void recordsTheFullMetricCatalog() {
+        SimpleMeterRegistry registry = new SimpleMeterRegistry();
+        MicrometerTelemetry telemetry = new MicrometerTelemetry(registry);
+
+        telemetry.bindActiveSessions(() -> 3);
+        telemetry.sessionOpened("/app");
+        telemetry.sessionOpened("/app");
+        telemetry.sessionClosed("/app");
+        telemetry.eventBatchReceived("/app", 5);
+        telemetry.batchFlushed("/app", 2, 7, 128, 1_000_000L);
+        telemetry.ssrRendered("/app", 2_000_000L);
+        telemetry.resyncRequested("/app");
+        telemetry.connectionFailed("/app", "boom");
+
+        assertEquals(2.0, counter(registry, "pathland.sessions.opened"));
+        assertEquals(1.0, counter(registry, "pathland.sessions.closed"));
+        assertEquals(5.0, counter(registry, "pathland.events.received"));
+        assertEquals(1.0, counter(registry, "pathland.batches.sent"));
+        assertEquals(2.0, counter(registry, "pathland.frames.sent"));
+        assertEquals(128.0, counter(registry, "pathland.bytes.sent"));
+        assertEquals(1.0, counter(registry, "pathland.resync.requested"));
+        assertEquals(1.0, counter(registry, "pathland.ws.failures"));
+        assertEquals(1, registry.get("pathland.ssr.render").tag("mount", "/app").timer().count());
+        assertEquals(1, registry.get("pathland.batch.flush").tag("mount", "/app").timer().count());
+        assertEquals(7.0, registry.get("pathland.batch.size").tag("mount", "/app").summary().totalAmount());
+        assertEquals(3.0, registry.get("pathland.sessions.active").gauge().value());
+    }
+
+    @Test
+    void tagsSeriesByMount() {
+        SimpleMeterRegistry registry = new SimpleMeterRegistry();
+        MicrometerTelemetry telemetry = new MicrometerTelemetry(registry);
+
+        telemetry.sessionOpened("/a");
+        telemetry.sessionOpened("/b");
+        telemetry.sessionOpened("/b");
+
+        assertEquals(1.0, counter(registry, "pathland.sessions.opened", "/a"));
+        assertEquals(2.0, counter(registry, "pathland.sessions.opened", "/b"));
+    }
+
+    private static double counter(SimpleMeterRegistry registry, String name) {
+        return counter(registry, name, "/app");
+    }
+
+    private static double counter(SimpleMeterRegistry registry, String name, String mount) {
+        return registry.get(name).tag("mount", mount).counter().count();
+    }
+}

Index: lib/java/pathland-observability/src/test/java/dev/pathland/observability/TracingTelemetryTest.java
===================================================================
--- lib/java/pathland-observability/src/test/java/dev/pathland/observability/TracingTelemetryTest.java	
+++ lib/java/pathland-observability/src/test/java/dev/pathland/observability/TracingTelemetryTest.java	
@@ -0,0 +1,79 @@
+package dev.pathland.observability;
+
+import dev.pathland.server.PathlandTelemetry;
+import io.opentelemetry.api.trace.Tracer;
+import io.opentelemetry.sdk.testing.exporter.InMemorySpanExporter;
+import io.opentelemetry.sdk.trace.SdkTracerProvider;
+import io.opentelemetry.sdk.trace.export.SimpleSpanProcessor;
+import io.opentelemetry.sdk.trace.data.SpanData;
+import org.junit.jupiter.api.Test;
+
+import java.util.List;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/**
+ * The OTel decorator: frame sends, event batches, and SSR renders each emit a span
+ * with the expected name, and the wrapped telemetry still receives every event.
+ */
+class TracingTelemetryTest {
+
+    @Test
+    void emitsSpansAndStillDelegates() {
+        InMemorySpanExporter exporter = InMemorySpanExporter.create();
+        SdkTracerProvider provider = SdkTracerProvider.builder()
+                .addSpanProcessor(SimpleSpanProcessor.create(exporter))
+                .build();
+        Tracer tracer = provider.get("pathland-test");
+
+        Recording delegate = new Recording();
+        TracingTelemetry telemetry = new TracingTelemetry(delegate, tracer);
+
+        telemetry.batchFlushed("/app", 2, 7, 128, 1_000_000L);
+        telemetry.eventBatchReceived("/app", 4);
+        telemetry.ssrRendered("/app", 2_000_000L);
+        telemetry.sessionOpened("/app");
+
+        List<SpanData> spans = exporter.getFinishedSpanItems();
+        assertEquals(3, spans.size(), "frame + event + ssr spans");
+        assertTrue(spans.stream().anyMatch(s -> s.getName().equals("pathland.frame.send")));
+        assertTrue(spans.stream().anyMatch(s -> s.getName().equals("pathland.event.batch")));
+        assertTrue(spans.stream().anyMatch(s -> s.getName().equals("pathland.ssr.render")));
+
+        // Every event still reaches the wrapped telemetry (metrics keep flowing).
+        assertEquals(1, delegate.batchFlushed);
+        assertEquals(1, delegate.eventBatchReceived);
+        assertEquals(1, delegate.ssrRendered);
+        assertEquals(1, delegate.sessionOpened);
+
+        provider.close();
+    }
+
+    private static final class Recording implements PathlandTelemetry {
+        int sessionOpened;
+        int batchFlushed;
+        int eventBatchReceived;
+        int ssrRendered;
+
+        @Override
+        public void sessionOpened(String mount) {
+            sessionOpened++;
+        }
+
+        @Override
+        public void batchFlushed(String mount, int frames, int opcodes, int bytes, long nanos) {
+            batchFlushed++;
+        }
+
+        @Override
+        public void eventBatchReceived(String mount, int events) {
+            eventBatchReceived++;
+        }
+
+        @Override
+        public void ssrRendered(String mount, long nanos) {
+            ssrRendered++;
+        }
+    }
+}

