-
-        // ProtocolFrame 1: SET_TEXT "ab" (offset 0) + a numeric VALUE change.
-        byte[] strings1 = stringSection("ab");
-        ProtocolFrame f1 = new ProtocolFrame(List.of(
-                new Opcode(Categories.PARAMETER, Commands.Parameter.SET_TEXT, 0, 1, 0, 0),
