+        assertEquals(200f, node.properties.get(Properties.WIDTH));
+        assertFalse(node.properties.containsKey(Properties.HEIGHT));
+        assertEquals((float) Alignment.TOP_LEADING.wire(), node.properties.get(Properties.ALIGNMENT));
+    }
+
+    @Test
