+                .idealWidth(200)
+                .maxWidth(300)
+                .alignment(Alignment.CENTER)));
+        assertEquals(100f, node.properties.get(Properties.MIN_WIDTH));
+        assertEquals(200f, node.properties.get(Properties.IDEAL_WIDTH));
