+                .map(o -> Float.intBitsToFloat(o.c()))
+                .orElse(null);
+    }
+
+    /** The U32 value of a node property (last one wins), or null. */
+    private static Integer uintProp(ProtocolFrame frame, int nodeId, int property) {
